#!/usr/bin/env python3
"""Deux commentaires originaux et leurs exercices. Source : commentaires-programme-data.json.
Relancer après modification des données ; les pages générées sont versionnées.
"""
from pathlib import Path
import json,html,re
ROOT=Path(__file__).resolve().parent.parent
DATA=json.loads((ROOT/'scripts/commentaires-programme-data.json').read_text())
def esc(s):return html.escape(str(s),quote=True)
def paras(s):return ''.join('<p>'+esc(p)+'</p>' for p in s.split('\n'))
def page(title,description,body,scripts):
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' | La Phrase Juste</title><meta name="description" content="'+esc(description)+'"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="commentaires-programme.css"><link rel="stylesheet" href="paratexte.css"></head><body><main class="wrap programme-commentaire">'+body+'</main>'+''.join('<script src="'+s+'"></script>' for s in scripts)+'<script src="site-nav.js"></script></body></html>\n'
def source(w):
 return '<section class="programme-source" aria-label="Le texte à commenter"><h3>'+esc(w['title'])+'</h3><p class="micro">'+esc(w['reference'])+'</p><p class="texte-chapeau"><em>'+esc(w['chapeau'])+'</em></p><div class="programme-reading" tabindex="0" role="region" aria-label="Extrait intégral, défilement possible">'+w['support']+'</div><p class="micro">'+esc(w['sourceNote'])+'</p><p><a href="'+esc(w['source'])+'">Consulter la source →</a></p></section>'
def writing(w,e):
 return '<div class="programme-writing"><label class="instruction" for="reponse-'+esc(e['id'])+'">'+esc(e['write']).replace('\n','<br>')+'</label><textarea id="reponse-'+esc(e['id'])+'" rows="5" data-programme-draft data-feedback="off"></textarea><p class="programme-status micro" role="status"></p><details><summary>Un indice</summary><p>'+esc(e['hint'])+'</p></details><details data-after-writing><summary>Comparer avec une réponse possible</summary>'+paras(e['model'])+'<ul>'+''.join('<li>'+esc(c)+'</li>' for c in e['checks'])+'</ul><p>Comparez votre essai, puis reprenez-le. Plusieurs formulations sont possibles.</p></details></div>'
def commentary(w,other):
 body='<section class="pagehead"><div><div class="kicker">PREMIÈRE · ŒUVRE AU PROGRAMME · COMMENTAIRE</div><h1>'+esc(w['author'])+'<br>'+esc(w['work'])+'</h1><p class="lede">'+esc(w['title'])+' : lire le texte, choisir, écrire, puis comparer.</p></div></section>'
 body+='<div class="onglets" data-onglets data-defaut="entrainement"><div class="onglets-barre" role="tablist" aria-label="Ce commentaire"><button role="tab" aria-controls="texte">Le texte</button><button role="tab" aria-controls="entrainement">S’entraîner</button><button role="tab" aria-controls="copie">Le commentaire modèle</button></div>'
 body+='<section class="onglet" id="texte">'+source(w)+(('<details><summary>Comparer trois vers du texte ancien</summary><p>Vers 375–377 de l’édition de 1850 ; ponctuation et capitales modernisées.</p><blockquote>'+esc(w['oldFrench']).replace('\n','<br>')+'</blockquote><p>La traduction de travail ci-dessus rend ces vers ainsi : « Amour le veut, il saute : peu lui importe la honte, puisqu’Amour le commande et le veut. »</p></details>') if w.get('oldFrench') else '')+'<p><a class="btn red" href="#entrainement">Commencer les exercices →</a></p><details><summary>À quel entraînement cet extrait sert-il ?</summary><p>Ce passage continu permet un commentaire organisé qui suit les mouvements du texte. Les trois parties sont des réponses à une question de lecture, pas une liste de procédés.</p><p>Une œuvre au programme ne fournit pas le texte du commentaire écrit officiel. Ce support est un entraînement original au commentaire et à la préparation de l’oral. Pour une présentation orale, le professeur ou l’examinateur délimite un passage adapté à la durée de l’épreuve.</p><p>Parcours : '+esc(w['parcours'])+'. Programme de Première 2026–2027, écrit de français en juin 2027 (baccalauréat, session 2028).</p><p><a href="https://www.education.gouv.fr/bo/2025/Hebdo30/MENE2518792N">Programme officiel ↗</a> · <a href="https://www.education.gouv.fr/bo/20/Special7/MENE2019312N.htm">Définition officielle des épreuves ↗</a></p></details></section>'
 body+='<section class="onglet" id="entrainement"><h2>Une étape à la fois.</h2><div class="boussole"><p><b>D’où vous partez</b>Le texte, disponible à côté des questions.</p><p><b>Ce que vous faites</b>Vous choisissez une lecture, puis vous écrivez avec vos mots.</p><p><b>Ce que vous obtenez</b>Un plan expliqué, une analyse précise, puis votre commentaire.</p></div><div class="programme-work-grid"><aside>'+source(w)+'</aside><div data-etapes data-ecrit-label="À vous d’écrire →">'
 body+='<div class="etapes-nav" role="group" aria-label="Étapes">'+''.join('<button type="button" data-etape="'+str(i)+'">'+str(i+1)+' · '+t+'</button>' for i,t in enumerate(['Comprendre','Le plan','L’analyse','Écrire seul']))+'</div>'
 for i,e in enumerate(w['exercises']):
  options=''.join('<button type="button" class="chaine-opt" data-v="'+c[1]+'" data-why="'+esc(c[2])+'">'+esc(c[0])+'</button>' for c in e['choices'])
  body+='<section class="etape" id="etape-'+esc(e['id'])+'"><h3>'+str(i+1)+' · '+esc(e['title'])+'</h3><button type="button" class="etape-direct" hidden>Je sais déjà faire : passer à l’écrit →</button><div class="etape-q"><p class="chaine-q">'+esc(e['question'])+'</p><div class="chaine-opts">'+options+'</div><div class="chaine-fb" aria-live="polite"></div></div><div class="etape-ecrit"><h4>À vous d’écrire</h4>'+writing(w,e)+'</div><div class="etape-fin"><button type="button" class="btn red small etape-suivante">Étape suivante →</button><button type="button" data-recommencer>Reprendre les choix</button></div></section>'
 body+='<section class="etape" id="etape-copie"><h3>4 · Écrire seul</h3><label class="instruction" for="copie-personnelle">Rédigez votre commentaire du passage. Organisez vos analyses autour de votre question de lecture.</label><textarea id="copie-personnelle" rows="18" data-programme-draft data-feedback="off"></textarea><p class="programme-status micro" role="status"></p><p><a class="btn red" href="#copie">Comparer avec le commentaire modèle →</a></p><p><a href="'+other['file']+'#etape-copie">Refaire seul sur un autre texte →</a></p></section></div></div></section>'
 body+='<section class="onglet" id="copie"><h2>Un commentaire qui suit les mouvements du texte.</h2><p>'+esc(w['problem'])+'</p><article class="c20" id="commentaire-modele">'
 for para in w['copy']:
  body+='<div class="c20-block"><h3 class="c20-h">'+esc(para['heading'])+'</h3>'
  for s in para['sentences']:body+='<p class="c20-s"><span class="c20-t">'+esc(s['text'])+'</span><span class="c20-f">'+esc(s['function'])+'</span></p>'
  body+='</div>'
 body+='</article><details><summary>Comment lire les analyses ?</summary><p>Une réalisation, c’est ce que le texte fait : par exemple, opposer deux conduites. Les mots cités en donnent la preuve ; le procédé nomme leur construction ; l’effet dit précisément ce que cette construction fait comprendre ici.</p><p>Reliez toujours le procédé aux mots précis du texte et à ce qu’ils font comprendre dans le passage. Une figure n’a pas d’effet automatique et le plan en trois parties n’est pas une obligation nationale.</p><p>L’allégorie représente une idée abstraite par une image ou une scène ; dans Lancelot, Raison et Amour deviennent des puissances qui parlent et commandent. <a href="https://www.cnrtl.fr/definition/all%C3%A9gorie">Définition du TLFi, CNRTL ↗</a></p><p><a href="manuel-procedes.html">Le petit manuel des procédés →</a></p></details><p><a href="#etape-copie">Reprendre votre commentaire →</a></p></section></div>'
 body+='<section class="offer-band"><h2>Passer à la dissertation sur cette œuvre.</h2><p>Un jugement authentique à discuter, avec trois exercices courts.</p><a href="'+w['dissertation']['file']+'">Ouvrir le sujet original de dissertation →</a></section>'
 (ROOT/w['file']).write_text(page(w['author']+' — '+w['title'],'Extrait lisible, exercices au clic et à l’écrit, commentaire modèle bref et fonction de chaque phrase.',body,['onglets.js','etapes.js','commentaires-programme.js']))
def dissertation(w):
 d=w['dissertation'];body='<section class="pagehead"><div><div class="kicker">DISSERTATION · SUJET D’ENTRAÎNEMENT ORIGINAL — NON OFFICIEL</div><h1>'+esc(w['work'])+'</h1><p class="lede">Une affirmation littéraire à examiner dans l’œuvre.</p></div></section><section class="dissertation-sujet" id="sujet"><p>'+esc(d['introduction'])+'</p><blockquote>« '+esc(d['quote'])+' »</blockquote><p class="dissertation-question"><strong>'+esc(d['question'])+'</strong></p><p>Vous répondrez à cette question dans un développement organisé, en vous appuyant sur votre connaissance de l’œuvre, sur le parcours « '+esc(w['parcours'])+' » et sur votre culture littéraire.</p><details><summary>La référence de la citation</summary><p class="dissertation-citation-reference">'+esc(d['reference'])+'</p>'+('<p><a href="'+esc(d['sourcePrimary'])+'">Dossier préparatoire numérisé — BnF ↗</a></p>' if d.get('sourcePrimary') else '')+('<p><a href="'+esc(d['source'])+'">Consulter la publication citée ↗</a></p>' if d['source'] else '')+'</details></section><section id="entrainement"><h2>Préparer votre lecture du sujet.</h2><div class="boussole"><p><b>D’où vous partez</b>Le jugement cité et votre connaissance de l’œuvre.</p><p><b>Ce que vous faites</b>Vous expliquez ses mots, puis vous les confrontez aux passages.</p><p><b>Ce que vous obtenez</b>Votre question de dissertation.</p></div>'
 for i,(t,q,m) in enumerate(d['tasks']):
  body+='<section class="offer-band programme-writing"><h3>'+str(i+1)+' · '+esc(t)+'</h3><label class="instruction" for="dissertation-'+str(i)+'">'+esc(q)+'</label><textarea id="dissertation-'+str(i)+'" rows="5" data-programme-draft data-feedback="off"></textarea><p class="programme-status micro" role="status"></p><details data-after-writing><summary>Comparer avec des pistes</summary><p>'+esc(m)+'</p><p>Ces pistes proposent une lecture, sans imposer une formulation ou un plan unique.</p></details></section>'
 body+='</section><p><a href="'+w['file']+'#texte">Étudier un extrait de l’œuvre →</a> · <a href="bac-dissertation-methode.html">La méthode de dissertation →</a></p><p class="micro">Ce sujet a été conçu pour l’entraînement ; ce n’est pas une annale ni une prédiction de sujet officiel.</p>'
 (ROOT/d['file']).write_text(page(w['work']+' — sujet de dissertation sur une citation',d['question']+' Sujet original, référence vérifiée et exercices pour problématiser littérairement.',body,['commentaires-programme.js']))
for i,w in enumerate(DATA):commentary(w,DATA[1-i]);dissertation(w)
print('Quatre pages : deux commentaires avec exercices, deux sujets originaux de dissertation.')
